use super::*;
#[test]
fn test_estimate_number_of_tables() {
    initialize_test_license();
    // Test case 1: Simple model with two trees using different feature combinations
    let json_str = r#"{
        "feature_names": ["feat1", "feat2", "feat3"],
        "tree_info": [
            {
                "tree_structure": {
                    "internal_value": 0.5,
                    "split_feature": 0,
                    "threshold": "1.0",
                    "decision_type": "<=",
                    "left_child": {
                        "split_feature": 1,
                        "threshold": "2.0",
                        "decision_type": "<=",
                        "left_child": {
                            "leaf_value": 0.3,
                            "leaf_index": 0
                        },
                        "right_child": {
                            "leaf_value": 0.4,
                            "leaf_index": 1
                        }
                    },
                    "right_child": {
                        "leaf_value": 0.7,
                        "leaf_index": 2
                    }
                }
            },
            {
                "tree_structure": {
                    "internal_value": 0.0,
                    "split_feature": 2,
                    "threshold": "3.0",
                    "decision_type": "<=",
                    "left_child": {
                        "leaf_value": 0.2,
                        "leaf_index": 0
                    },
                    "right_child": {
                        "leaf_value": 0.3,
                        "leaf_index": 1
                    }
                }
            }
        ]
    }"#;

    let num_tables = estimate_number_of_tables(json_str).unwrap();
    
    // Expected tables:
    // 1. Mean table (always present)
    // 2. Table for feat1 + feat2 combination (from first tree)
    // 3. Table for feat3 (from second tree)
    assert_eq!(num_tables, 3, "Expected 3 tables (mean + 2 feature combinations)");

    // Test case 2: Model with overlapping feature sets
    let json_str_2 = r#"{
        "feature_names": ["feat1", "feat2"],
        "tree_info": [
            {
                "tree_structure": {
                    "internal_value": 0.5,
                    "split_feature": 0,
                    "threshold": "1.0",
                    "decision_type": "<=",
                    "left_child": {
                        "leaf_value": 0.3,
                        "leaf_index": 0
                    },
                    "right_child": {
                        "leaf_value": 0.4,
                        "leaf_index": 1
                    }
                }
            },
            {
                "tree_structure": {
                    "internal_value": 0.0,
                    "split_feature": 0,
                    "threshold": "2.0",
                    "decision_type": "<=",
                    "left_child": {
                        "split_feature": 1,
                        "threshold": "1.0",
                        "decision_type": "<=",
                        "left_child": {
                            "leaf_value": 0.2,
                            "leaf_index": 0
                        },
                        "right_child": {
                            "leaf_value": 0.3,
                            "leaf_index": 1
                        }
                    },
                    "right_child": {
                        "leaf_value": 0.4,
                        "leaf_index": 2
                    }
                }
            }
        ]
    }"#;

    let num_tables_2 = estimate_number_of_tables(json_str_2).unwrap();
    
    // Expected tables:
    // 1. Mean table (always present)
    // 2. Table for feat1 + feat2 (from second tree)
    assert_eq!(num_tables_2, 2, "Expected 3 tables (mean + 1 feature combinations)");

    // Test case 4: Invalid JSON
    let invalid_json = "invalid json";
    assert!(estimate_number_of_tables(invalid_json).is_err(), "Should error on invalid JSON");

    // Test case 5: Model with multiple trees and complex feature interactions
    let json_str_3 = r#"{
        "feature_names": ["feat1", "feat2", "feat3", "feat4"],
        "tree_info": [
            {
                "tree_structure": {
                    "internal_value": 0.5,
                    "split_feature": 0,
                    "threshold": "1.0",
                    "decision_type": "<=",
                    "left_child": {
                        "split_feature": 1,
                        "threshold": "2.0",
                        "decision_type": "<=",
                        "left_child": {
                            "leaf_value": 0.3,
                            "leaf_index": 0
                        },
                        "right_child": {
                            "leaf_value": 0.4,
                            "leaf_index": 1
                        }
                    },
                    "right_child": {
                        "leaf_value": 0.7,
                        "leaf_index": 2
                    }
                }
            },
            {
                "tree_structure": {
                    "internal_value": 0.0,
                    "split_feature": 2,
                    "threshold": "3.0",
                    "decision_type": "<=",
                    "left_child": {
                        "split_feature": 3,
                        "threshold": "4.0",
                        "decision_type": "<=",
                        "left_child": {
                            "leaf_value": 0.2,
                            "leaf_index": 0
                        },
                        "right_child": {
                            "leaf_value": 0.3,
                            "leaf_index": 1
                        }
                    },
                    "right_child": {
                        "leaf_value": 0.4,
                        "leaf_index": 2
                    }
                }
            },
            {
                "tree_structure": {
                    "internal_value": 0.0,
                    "split_feature": 1,
                    "threshold": "5.0",
                    "decision_type": "<=",
                    "left_child": {
                        "split_feature": 3,
                        "threshold": "6.0",
                        "decision_type": "<=",
                        "left_child": {
                            "leaf_value": 0.5,
                            "leaf_index": 0
                        },
                        "right_child": {
                            "leaf_value": 0.6,
                            "leaf_index": 1
                        }
                    },
                    "right_child": {
                        "leaf_value": 0.7,
                        "leaf_index": 2
                    }
                }
            }
        ]
    }"#;

    let num_tables_3 = estimate_number_of_tables(json_str_3).unwrap();
    
    // Expected tables:
    // 1. Mean table (always present)
    // 2. Table for feat1 + feat2 combination (from first tree)
    // 3. Table for feat2 + feat3 combination (from second tree)
    // 4. Table for feat1 + feat3 combination (from third tree)
    assert_eq!(num_tables_3, 4, 
        "Expected 4 tables (mean + 3 unique feature combinations)");

    // Print debug information about the feature combinations
    println!("\nFeature combinations in multiple trees test:");
    println!("Tree 1: feat1 + feat2");
    println!("Tree 2: feat2 + feat3 + feat4");
    println!("Tree 3: feat1 + feat3");
    println!("Total unique tables (including mean): {}", num_tables_3);
}
