    let result = estimate_number_of_tables(json_str).unwrap();

    let rating_model=RatingModel::from_lgbm_json(json_str,"max").unwrap();
    let num_tables= rating_model.tables.len();
    
    // Print information about each table
    println!("\nActual tables in model:");
    for (i, table) in rating_model.tables.iter().enumerate() {
        println!("\nTable {}:", i);
        println!("Columns: {:?}", table.data.get_column_names());
        println!("Shape: {:?}", table.data.shape());
    }

    // Parse the JSON to examine tree structure
    let parsed: serde_json::Value = serde_json::from_str(json_str).unwrap();
    println!("\nTree information:");
    if let Some(trees) = parsed["tree_info"].as_array() {
        for (i, tree) in trees.iter().enumerate() {
            if let Some(structure) = tree["tree_structure"].as_object() {
                println!("\nTree {}:", i);
                println!("Split feature: {}", structure["split_feature"]);
                // Add more tree structure information as needed
            }
        }
    }
    assert_eq!(result, num_tables, "Expected expected number of tables to match len(rating_model.tables) (3 unique feature combinations + mean table)");
